// backend/audit/reporters/json.js
'use strict';

/**
 * Formats an audit report into machine-readable JSON for CI and tooling (Issue #78).
 * @param {Object} report - Raw audit report generated by audit()
 * @param {Object} [options] - Formatting options
 * @param {boolean} [options.pretty=true] - Whether to pretty-print JSON (2 spaces indentation)
 * @returns {string} Formatted JSON string
 */
function formatJsonReport(report = {}, options = {}) {
  const pretty = options.pretty !== false;
  const indent = pretty ? 2 : 0;

  const jsonObject = {
    version: '1.0.0',
    tool: 'dimsee-audit',
    timestamp: report.timestamp || new Date().toISOString(),
    status: report.passed ? 'passed' : 'failed',
    passed: Boolean(report.passed),
    summary: {
      total: (report.findings || []).length,
      errors: (report.counts && report.counts.error) || 0,
      warnings: (report.counts && report.counts.warn) || 0,
      info: (report.counts && report.counts.info) || 0
    },
    findings: (report.findings || []).map(f => ({
      id: f.id,
      rule: f.rule,
      severity: f.severity,
      title: f.title,
      message: f.message,
      remediation: f.remediation
    }))
  };

  return JSON.stringify(jsonObject, null, indent);
}

module.exports = {
  formatJsonReport
};
